import{_ as e,o,c as a,a4 as r}from"./chunks/framework.bruR1JhL.js";const p=JSON.parse('{"title":"Security, signing & size","description":"Add or remove PDF passwords and restrictions, sign PDFs by hand or with a certificate, make them smaller, and repair damaged files.","frontmatter":{"title":"Security, signing & size","description":"Add or remove PDF passwords and restrictions, sign PDFs by hand or with a certificate, make them smaller, and repair damaged files."},"headers":[],"relativePath":"docs/security.md","filePath":"docs/security.md","lastUpdated":1795509372000}'),s={name:"docs/security.md"};function n(i,t,d,l,h,g){return o(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="security-signing-size" tabindex="-1">Security, signing &amp; size <a class="header-anchor" href="#security-signing-size" aria-label="Permalink to &quot;Security, signing &amp; size&quot;">​</a></h1><p>These tools protect a PDF with a password or restrictions (or remove them), sign it, make it smaller, and recover damaged files. In the app this category is the <strong>Security</strong> tab under <strong>Documents</strong>.</p><p>Sign PDF and Compress PDF work on the same open PDF as the other PDF tools. Protect PDF and Repair PDF keep their own file, because they also have to open files the other tools can&#39;t: password-protected PDFs and damaged ones. To open a PDF, drag it from the Explorer onto the tool, click <strong>Open PDF…</strong>, or click <strong>Use</strong> followed by the name of the PDF selected in the Explorer. Right-clicking a PDF in the Explorer also offers <strong>Sign PDF</strong> and <strong>Protect PDF</strong>. See <a href="/tilepress/docs/interface">The Tilepress window</a> for the general controls.</p><p>Every tool saves a <strong>new</strong> file and leaves the original alone. When it&#39;s done, a <strong>Saved</strong> card lists the result with <strong>Open</strong>, <strong>Show in folder</strong> and <strong>Keep editing this file</strong>. Each run is listed in the <a href="/tilepress/docs/history">History</a>, but passwords never are: the History records which files a tool used and made, never the options you typed.</p><h2 id="protect-pdf" tabindex="-1">Protect PDF <a class="header-anchor" href="#protect-pdf" aria-label="Permalink to &quot;Protect PDF&quot;">​</a></h2><p>Protect PDF encrypts a PDF with a password, restricts what readers may do with it, or both. When you open a PDF that is already protected, the tool offers to unlock it instead.</p><h3 id="how-to-use-it" tabindex="-1">How to use it <a class="header-anchor" href="#how-to-use-it" aria-label="Permalink to &quot;How to use it&quot;">​</a></h3><ol><li>Open <strong>Protect PDF</strong> and open a PDF. Tilepress reads its security first.</li><li>To require a password to open the file, type it in <strong>Open password</strong> and again in <strong>Confirm</strong>.</li><li>To limit what people can do, untick the actions under <strong>Restrictions</strong>.</li><li>Optionally type a <strong>Permissions password</strong> and choose the <strong>Encryption</strong>.</li><li>Click <strong>Protect and save…</strong>, choose a name and folder, and click <strong>Save</strong>.</li></ol><p>You need an open password, at least one unticked restriction, or both. Otherwise the button stays greyed out and the bar says &quot;Set an open password or untick a permission.&quot;</p><h3 id="options" tabindex="-1">Options <a class="header-anchor" href="#options" aria-label="Permalink to &quot;Options&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Option</th><th>What it does</th><th>Default</th></tr></thead><tbody><tr><td><strong>Open password</strong></td><td>The password needed to open the file. Leave it empty to let anyone open it.</td><td>Empty</td></tr><tr><td><strong>Confirm</strong></td><td>Type the open password again. A message tells you if they don&#39;t match.</td><td></td></tr><tr><td><strong>Show passwords</strong></td><td>Shows the passwords as you type instead of dots.</td><td>Off</td></tr><tr><td><strong>Restrictions</strong></td><td>What readers may do: <strong>Printing</strong>, <strong>High-quality printing</strong>, <strong>Copying text and images</strong>, <strong>Editing the content</strong>, <strong>Comments and annotations</strong>, <strong>Filling in forms</strong>, <strong>Inserting, deleting and rotating pages</strong>, <strong>Text access for screen readers</strong>. Untick what you want to forbid.</td><td>All allowed</td></tr><tr><td><strong>Permissions password</strong></td><td>The password needed to change the restrictions. It must differ from the open password. If you leave it empty, Tilepress makes up a random one and doesn&#39;t show it.</td><td>Empty (random)</td></tr><tr><td><strong>Encryption</strong></td><td><strong>AES 256-bit (recommended)</strong>, AES 128-bit for older readers, or <strong>RC4 128-bit (old readers)</strong>.</td><td>AES 256-bit</td></tr></tbody></table><h3 id="unlock" tabindex="-1">Unlock <a class="header-anchor" href="#unlock" aria-label="Permalink to &quot;Unlock&quot;">​</a></h3><p>If the PDF you open is already protected, the tool says so. It tells you whether the file needs a password to open or only has restrictions, and lists what isn&#39;t allowed.</p><ol><li>Type the password under <strong>Remove the protection</strong>. For a file that needs a password to open, this is the open or the permissions password.</li><li>Click <strong>Unlock and save…</strong>, choose a name and folder, and click <strong>Save</strong>.</li></ol><p>The saved copy has no password and no restrictions. Only remove protection from documents you own or are allowed to change.</p><h3 id="good-to-know" tabindex="-1">Good to know <a class="header-anchor" href="#good-to-know" aria-label="Permalink to &quot;Good to know&quot;">​</a></h3><ul><li>The file is suggested as <code>name_protected.pdf</code> (or <code>name_unlocked.pdf</code>) next to the original.</li><li>An open password is real encryption: without it, nobody can read the file. Restrictions are different. PDF readers are expected to respect them, but they aren&#39;t a strong barrier on their own.</li><li>A file that opens without a password but has restrictions can be unlocked here without typing anything.</li><li>Tilepress can&#39;t protect a file that is already protected. Unlock it first.</li><li>A password-protected PDF opens only in Protect PDF and <a href="#repair-pdf">Repair PDF</a>. Unlock a copy first to use it in the other tools.</li><li><strong>Keep editing this file</strong> opens the result in Protect PDF again, where it shows as protected.</li><li>Passwords aren&#39;t stored anywhere, including the <a href="/tilepress/docs/history">History</a>.</li></ul><h2 id="sign-pdf" tabindex="-1">Sign PDF <a class="header-anchor" href="#sign-pdf" aria-label="Permalink to &quot;Sign PDF&quot;">​</a></h2><p>Sign PDF adds a signature in one of two ways. An <strong>electronic signature</strong> is a picture of your handwritten signature placed on the page. A <strong>digital signature</strong> uses a certificate, so anyone can check later whether the file was changed after signing.</p><h3 id="how-to-use-it-1" tabindex="-1">How to use it <a class="header-anchor" href="#how-to-use-it-1" aria-label="Permalink to &quot;How to use it&quot;">​</a></h3><ol><li>Open <strong>Sign PDF</strong> and open a PDF.</li><li>Choose <strong>Electronic signature</strong> or <strong>Digital signature (certificate)</strong> at the top.</li><li>Follow the steps for that kind of signature below.</li></ol><p>If the PDF already has digital signatures, a <strong>Digital signatures in this file</strong> card appears at the top. See <a href="#checking-signatures">Checking signatures</a>.</p><h3 id="electronic-signature" tabindex="-1">Electronic signature <a class="header-anchor" href="#electronic-signature" aria-label="Permalink to &quot;Electronic signature&quot;">​</a></h3><ol><li>Make your signature in one of three ways: <ul><li><strong>Draw</strong>: sign in the box with your mouse, pen or finger. With a pen, pressing harder draws a thicker line.</li><li><strong>Type</strong>: type your name and choose a handwriting style.</li><li><strong>Upload image</strong>: click <strong>Choose a signature image…</strong> and pick a picture of your signature. A PNG with a transparent background looks best.</li></ul></li><li>For <strong>Draw</strong> and <strong>Type</strong>, pick an ink colour and click <strong>Use this signature</strong>. <strong>Clear</strong> starts again.</li><li>Click on the page to place the signature, or drag to give it a size. Place it as many times as you need, on any page. Drag a signature to move it, drag its handles to resize it.</li><li>Optionally click <strong>Add date</strong> to add today&#39;s date as text. Select it to change the text in the box that appears.</li><li>Click <strong>Save signed PDF…</strong>, choose a name and folder, and click <strong>Save</strong>.</li></ol><p>To remove a placed item, select it and press <kbd>Delete</kbd>, or click <strong>Remove selected</strong>. <strong>New signature</strong> lets you make a different one. The panel shows how many items you&#39;ve placed and on which pages.</p><h3 id="digital-signature" tabindex="-1">Digital signature <a class="header-anchor" href="#digital-signature" aria-label="Permalink to &quot;Digital signature&quot;">​</a></h3><ol><li>Under <strong>Certificate</strong>, click <strong>Choose .pfx / .p12…</strong> and pick your certificate file. If you don&#39;t have one, click <strong>Create a certificate…</strong> (see below).</li><li>Type the <strong>Certificate password</strong> and click <strong>Check</strong> (or press <kbd>Enter</kbd>). Tilepress shows who the certificate belongs to, who issued it (or &quot;Self-signed&quot;) and until when it&#39;s valid.</li><li>Fill in the <strong>Details</strong>: <strong>Reason</strong>, <strong>Location</strong> and <strong>Contact</strong>.</li><li>Leave <strong>Show a signature box on the page</strong> ticked to add a visible box. Until you place it, it sits at the bottom right of the page you&#39;re looking at (the last page at first). Click on a page to put it there, and drag its edges to resize it.</li><li>Click <strong>Sign and save…</strong>, choose a name and folder, and click <strong>Save</strong>.</li></ol><p><strong>Sign and save…</strong> stays greyed out until the certificate has been checked, and for an expired certificate.</p><h4 id="create-a-certificate" tabindex="-1">Create a certificate <a class="header-anchor" href="#create-a-certificate" aria-label="Permalink to &quot;Create a certificate&quot;">​</a></h4><ol><li>Click <strong>Create a certificate…</strong>.</li><li>Fill in <strong>Your name</strong>, and optionally <strong>Email</strong>, <strong>Organisation</strong> and <strong>Country (2 letters)</strong>.</li><li>Choose a <strong>Password (6+ characters)</strong> and type it again in <strong>Confirm</strong>.</li><li>Click <strong>Create and save…</strong>. The Save dialog suggests <code>Your name certificate.pfx</code> in your Documents folder.</li></ol><p>The new certificate is selected and checked straight away. Keep the file and its password safe: anyone who has both can sign as you.</p><h3 id="options-1" tabindex="-1">Options <a class="header-anchor" href="#options-1" aria-label="Permalink to &quot;Options&quot;">​</a></h3><p>Electronic signature:</p><table tabindex="0"><thead><tr><th>Option</th><th>What it does</th><th>Default</th></tr></thead><tbody><tr><td><strong>Draw</strong> / <strong>Type</strong> / <strong>Upload image</strong></td><td>How you make the signature.</td><td>Draw</td></tr><tr><td>Style (Type)</td><td><strong>Segoe Script</strong>, <strong>Lucida Handwriting</strong>, <strong>Ink Free</strong>, <strong>Segoe Print</strong> or <strong>Brush Script MT</strong>.</td><td>Segoe Script</td></tr><tr><td><strong>Ink</strong></td><td>Black, dark blue or dark green.</td><td>Black</td></tr><tr><td><strong>Add date</strong></td><td>Adds today&#39;s date as text near the bottom right of the page, in 11 pt Arial.</td><td></td></tr></tbody></table><p>Digital signature:</p><table tabindex="0"><thead><tr><th>Option</th><th>What it does</th><th>Default</th></tr></thead><tbody><tr><td><strong>Reason</strong></td><td>Why you sign. Stored in the signature and shown in the box.</td><td><code>I approve this document</code></td></tr><tr><td><strong>Location</strong></td><td>Where you sign. Stored in the signature.</td><td>Empty</td></tr><tr><td><strong>Contact</strong></td><td>How to reach you. Stored in the signature.</td><td>Empty</td></tr><tr><td><strong>Show a signature box on the page</strong></td><td>Adds a visible box reading &quot;Digitally signed by&quot; your name, the date and time, and the reason.</td><td>On</td></tr></tbody></table><h3 id="checking-signatures" tabindex="-1">Checking signatures <a class="header-anchor" href="#checking-signatures" aria-label="Permalink to &quot;Checking signatures&quot;">​</a></h3><p>When you open a signed PDF, each digital signature is listed with the signer&#39;s name, when it was signed, the reason, and one of these results:</p><table tabindex="0"><thead><tr><th>Message</th><th>Meaning</th></tr></thead><tbody><tr><td>Intact: the document has not changed since it was signed.</td><td>The signature covers the whole file and still matches.</td></tr><tr><td>Intact, but content was added after signing (for example another signature).</td><td>The signed part is unchanged, and more was added afterwards.</td></tr><tr><td>The document was changed after it was signed — this signature no longer matches.</td><td>The signed content has been altered.</td></tr><tr><td>The signature is not valid.</td><td>The signature itself doesn&#39;t check out.</td></tr></tbody></table><p>When a signature is intact but its certificate is self-signed, or doesn&#39;t come from an authority Windows trusts, the message adds a note saying so.</p><h3 id="good-to-know-1" tabindex="-1">Good to know <a class="header-anchor" href="#good-to-know-1" aria-label="Permalink to &quot;Good to know&quot;">​</a></h3><ul><li>The file is suggested as <code>name_signed.pdf</code> next to the original.</li><li>An electronic signature is a picture drawn into the page. It looks like a signature but doesn&#39;t protect the file from changes. In the History it&#39;s listed as &quot;Edit PDF&quot;.</li><li>A digital signature uses the PAdES format with SHA-256. Tilepress adds it as an update at the end of the file, so the original content stays byte for byte as it was. Signing again adds another signature (named <code>Signature1</code>, <code>Signature2</code>…), and earlier signatures stay intact.</li><li>The signing time comes from your computer&#39;s clock. No time-stamp server is contacted.</li><li>A certificate you create is self-signed: an RSA 3072-bit key, valid for three years. It proves the file hasn&#39;t changed since you signed it, but PDF readers will show you as not verified. For a trusted signature, use a certificate from a certificate authority.</li><li>Tilepress remembers which certificate file you used last, but never its password.</li><li>Checking signatures happens on your computer. Tilepress doesn&#39;t download revocation lists or contact any server.</li><li>Typed signatures use handwriting fonts that come with Windows. If one is missing, a generic handwriting-style font is used instead.</li><li>A digital signature can&#39;t be added to a protected PDF, even one that only has restrictions. Remove the protection first with <a href="#protect-pdf">Protect PDF</a>.</li></ul><h2 id="compress-pdf" tabindex="-1">Compress PDF <a class="header-anchor" href="#compress-pdf" aria-label="Permalink to &quot;Compress PDF&quot;">​</a></h2><p>Compress PDF makes a PDF smaller. It shrinks and re-encodes large pictures, merges duplicate parts of the file and compresses the page content.</p><h3 id="how-to-use-it-2" tabindex="-1">How to use it <a class="header-anchor" href="#how-to-use-it-2" aria-label="Permalink to &quot;How to use it&quot;">​</a></h3><ol><li>Open <strong>Compress PDF</strong> and open a PDF.</li><li>Choose a level: <strong>Light</strong>, <strong>Balanced</strong> or <strong>Strong</strong>.</li><li>Optionally tick <strong>Also remove metadata, thumbnails and embedded XMP</strong>.</li><li>Click <strong>Compress and save…</strong>, choose a name and folder, and click <strong>Save</strong>.</li></ol><p>When it&#39;s done, a card shows the size <strong>Before</strong> and <strong>After</strong>, how much was <strong>Saved</strong>, and how many pictures were re-encoded.</p><h3 id="options-2" tabindex="-1">Options <a class="header-anchor" href="#options-2" aria-label="Permalink to &quot;Options&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Option</th><th>What it does</th><th>Default</th></tr></thead><tbody><tr><td><strong>Light</strong></td><td>Pictures larger than 2400 pixels on their longest side are scaled down, and pictures are re-encoded as JPEG at quality 85. Best for printing.</td><td></td></tr><tr><td><strong>Balanced</strong></td><td>Pictures up to 1600 pixels, JPEG quality 72. Good on screen and for email.</td><td>Selected</td></tr><tr><td><strong>Strong</strong></td><td>Pictures up to 1100 pixels, JPEG quality 55. Smallest file.</td><td></td></tr><tr><td><strong>Also remove metadata, thumbnails and embedded XMP</strong></td><td>Also removes the document&#39;s properties (title, author, and so on) and its XMP metadata.</td><td>Off</td></tr></tbody></table><h3 id="good-to-know-2" tabindex="-1">Good to know <a class="header-anchor" href="#good-to-know-2" aria-label="Permalink to &quot;Good to know&quot;">​</a></h3><ul><li>The file is suggested as <code>name_compressed.pdf</code> next to the original.</li><li>A picture is only replaced if the new version is at least 10% smaller.</li><li>Some pictures are left as they are: ones with transparency or a mask, black-and-white scans (1-bit), and pictures stored as JBIG2, CCITT fax or JPEG 2000.</li><li>Pictures that are re-encoded become JPEGs. CMYK pictures are converted to RGB, so for professional printing <strong>Light</strong> or no compression may be the better choice.</li><li>Page thumbnails and leftover editing data are removed at every level, whether or not the box is ticked.</li><li>If the file can&#39;t get smaller, the copy is saved unchanged and the card says &quot;This PDF is already well optimised; the copy is unchanged.&quot;</li><li>A password-protected PDF can&#39;t be compressed. Unlock a copy with <a href="#protect-pdf">Protect PDF</a> first.</li></ul><h2 id="repair-pdf" tabindex="-1">Repair PDF <a class="header-anchor" href="#repair-pdf" aria-label="Permalink to &quot;Repair PDF&quot;">​</a></h2><p>Repair PDF checks a PDF for damage, lists what&#39;s wrong, and rebuilds it so it opens again. It also works on files the other tools can&#39;t open.</p><h3 id="how-to-use-it-3" tabindex="-1">How to use it <a class="header-anchor" href="#how-to-use-it-3" aria-label="Permalink to &quot;How to use it&quot;">​</a></h3><ol><li>Open <strong>Repair PDF</strong> and open a PDF. Tilepress checks the file straight away.</li><li>Read the result: <strong>No problems found</strong>, or how many problems were found with a list of them (up to 12 are shown). It also shows the file size and how many pages can be read.</li><li>Click <strong>Repair and save…</strong>, choose a name and folder, and click <strong>Save</strong>.</li></ol><p>Under the result, a line tells you which method recovered the file.</p><h3 id="options-3" tabindex="-1">Options <a class="header-anchor" href="#options-3" aria-label="Permalink to &quot;Options&quot;">​</a></h3><p>Repair PDF has no options. It tries every method and keeps the best result.</p><h3 id="good-to-know-3" tabindex="-1">Good to know <a class="header-anchor" href="#good-to-know-3" aria-label="Permalink to &quot;Good to know&quot;">​</a></h3><ul><li>The file is suggested as <code>name_repaired.pdf</code> next to the original.</li><li>The check looks for a missing PDF header or end-of-file marker (a file that was cut short), tries to read the file strictly and leniently, tries to open it with the PDF renderer, and collects any warnings.</li><li>The repair tries these methods and keeps the one that recovers the most pages: <ul><li>rewriting the file with a fresh cross-reference table, skipping pages that are broken,</li><li>the PDF renderer&#39;s own recovery mode,</li><li>for a file that was cut short, scanning it for every complete object and adding a new index, either using the document&#39;s own page list or building a new one from every page found.</li></ul></li><li>A page list built from scratch puts pages in the order they appear in the file, which may not be the original order.</li><li>If no method recovers a single page, you get the message &quot;The file is too damaged to recover any pages&quot;.</li><li>You can repair a healthy file too, for example to drop leftover data.</li><li><strong>Keep editing this file</strong> opens the repaired PDF in <a href="/tilepress/docs/edit">Edit PDF</a>.</li></ul>',60)])])}const u=e(s,[["render",n]]);export{p as __pageData,u as default};
